PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS candidates (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  slug TEXT NOT NULL UNIQUE,
  current_role TEXT,
  photo_url TEXT,
  website TEXT,
  wikipedia_url TEXT,
  bio TEXT,
  ai_ballot_brief TEXT,
  ai_topic_stances TEXT,
  ai_position_vector TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS motions (
  id TEXT PRIMARY KEY,
  resolution TEXT NOT NULL,
  motion_summary TEXT,
  meeting_date TEXT NOT NULL,
  meeting_url TEXT,
  meeting_type TEXT,
  topic TEXT,
  impact TEXT,
  report_numbers TEXT,
  calendar_event_url TEXT,
  agenda_url TEXT,
  minutes_url TEXT,
  source_dataset_id TEXT,
  source_api_url TEXT,
  source_portal_url TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  council_result TEXT,
  council_for INTEGER,
  council_against INTEGER,
  council_absent INTEGER
);

CREATE TABLE IF NOT EXISTS votes (
  id TEXT PRIMARY KEY,
  candidate_id TEXT NOT NULL REFERENCES candidates(id),
  motion_id TEXT REFERENCES motions(id),
  motion_title TEXT NOT NULL,
  motion_summary TEXT,
  vote TEXT NOT NULL,
  meeting_date TEXT NOT NULL,
  meeting_url TEXT,
  meeting_type TEXT,
  topic TEXT,
  impact TEXT,
  confidence TEXT NOT NULL,
  ai_extraction_notes TEXT,
  verified_by TEXT,
  verified_at TEXT,
  source_text TEXT,
  report_numbers TEXT,
  data_source_row_id TEXT,
  source_dataset_id TEXT,
  source_row_id TEXT,
  source_api_url TEXT,
  source_portal_url TEXT,
  source_hash TEXT,
  calendar_event_url TEXT,
  agenda_url TEXT,
  minutes_url TEXT,
  fetched_at TEXT,
  processed_at TEXT,
  prompt_version TEXT,
  model_version TEXT,
  ai_response_tokens INTEGER,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS platform_stances (
  id TEXT PRIMARY KEY,
  candidate_id TEXT NOT NULL REFERENCES candidates(id),
  campaign_page_id TEXT,
  topic TEXT,
  title TEXT NOT NULL,
  stance_summary TEXT,
  quote TEXT NOT NULL,
  source_url TEXT NOT NULL,
  source_scroll_url TEXT,
  confidence TEXT NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS motion_explainers (
  motion_key TEXT PRIMARY KEY,
  data TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS pairwise_briefs (
  id TEXT PRIMARY KEY,
  candidate_a_slug TEXT NOT NULL,
  candidate_b_slug TEXT NOT NULL,
  data TEXT NOT NULL
);

